cat > lib/billing-lock.ts <<'EOF'
/**
 * The read-only lock a workspace falls under while its subscription is not in
 * good standing.
 *
 * `lockReasonFor()` is the one statement of the rule; the service layer asks
 * `BillingService.assertWorkspaceWritable()`, which evaluates it against the
 * stored subscription at the moment of each write.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Raised when a member attempts a write in a locked workspace. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only: ${describeLockReason(reason)}`);
    this.name = "WorkspaceLockedError";
  }
}

/** Human-readable explanation of a lock, shared by the error and the banner. */
export function describeLockReason(reason: WorkspaceLockReason): string {
  switch (reason) {
    case "past_due":
      return "the subscription payment is past due";
    case "canceled":
      return "the subscription has been canceled";
    case "trial_ended":
      return "the trial has ended";
  }
}

/** True once `at` has been reached; an unreadable timestamp counts as reached. */
function hasReached(at: string, now: Date): boolean {
  const time = new Date(at).getTime();
  return Number.isNaN(time) || now.getTime() >= time;
}

/**
 * Why a workspace is locked at `now`, or `null` when it is writable.
 *
 * - no subscription row, or `active`: writable;
 * - `past_due`: locked;
 * - `trialing`: locked once the period end is reached;
 * - `canceled`: locked once the cancellation date is reached — a cancellation
 *   scheduled for later stays writable until then, and one with no date
 *   counts as canceled already.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      return subscription.cancelAt === null ||
        hasReached(subscription.cancelAt, now)
        ? "canceled"
        : null;
    default:
      return null;
  }
}
EOF
