/**
 * The read-only lock: `lockReasonFor` and the gate services apply after the
 * permission check.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { lockReasonFor, WorkspaceLockedError } from "@/lib/billing-lock";
import { isDomainError, toAppError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { getDb, subscriptions } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import * as issueService from "@/server/services/issue-service";
import * as organizationService from "@/server/services/organization-service";
import { eq } from "drizzle-orm";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Subscription, SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

const NOW = new Date("2026-06-15T12:00:00.000Z");
const EARLIER = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
const LATER = "2026-07-01T00:00:00.000Z" as IsoTimestamp;

function subscription(overrides: Partial<Subscription>): Subscription {
  return {
    id: "sub" as Subscription["id"],
    orgId: "org" as OrgId,
    plan: "starter",
    interval: "monthly",
    status: "active",
    seats: 1,
    currentPeriodStart: EARLIER,
    currentPeriodEnd: LATER,
    cancelAt: null,
    createdAt: EARLIER,
    updatedAt: EARLIER,
    ...overrides,
  };
}

async function setStatus(
  orgId: OrgId,
  status: SubscriptionStatus,
  cancelAt: string | null = null,
): Promise<void> {
  getDb()
    .update(subscriptions)
    .set({ status, cancelAt })
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

describe("lib/billing-lock lockReasonFor", () => {
  it("treats a missing or active subscription as writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
    expect(lockReasonFor(subscription({ status: "active" }), NOW)).toBeNull();
    expect(
      lockReasonFor(subscription({ status: "active", cancelAt: EARLIER }), NOW),
    ).toBeNull();
  });

  it("locks a past-due subscription", () => {
    expect(lockReasonFor(subscription({ status: "past_due" }), NOW)).toBe(
      "past_due",
    );
  });

  it("locks a trial at, not before, its period end", () => {
    const trial = subscription({
      status: "trialing",
      currentPeriodEnd: NOW.toISOString() as IsoTimestamp,
    });
    expect(lockReasonFor(trial, new Date(NOW.getTime() - 1))).toBeNull();
    expect(lockReasonFor(trial, NOW)).toBe("trial_ended");
    expect(lockReasonFor(trial, new Date(NOW.getTime() + 1))).toBe(
